-- AI Studio (#55, PLAN 5.12): asynchronous image jobs of a seller, from one original product photo.
--
-- QUEUED -> PROCESSING -> REVIEW_REQUIRED -> APPROVED | FAILED | CANCELLED. A failed job may be queued again a
-- limited number of times (max_attempts). Generated files live in the private bucket (ai_assets.storage_key)
-- until the seller approves one: only then is it copied to the public bucket as a new product photo with
-- ai_generated = true. The original photo is never changed.
--
-- 1. ai_jobs: one request of a seller (kind, source photo, status, attempts).
-- 2. ai_job_attempts: every call to the provider (provider id, outcome, cost in the provider's currency).
-- 3. ai_assets: the files a successful attempt produced.
-- 4. ai_approvals: the seller's decision on a job (APPROVED with the chosen asset, or REJECTED).
-- 5. ai_usage: attempts and cost per store and day, for the daily quota and the monthly hard cost limit.
--
-- The version number leaves room for migrations of parallel branches (V20-V39).

CREATE TABLE ai_jobs
(
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    store_id        BIGINT      NOT NULL REFERENCES stores (id) ON DELETE CASCADE,
    product_id      BIGINT      NOT NULL REFERENCES products (id) ON DELETE CASCADE,
    -- The original photo; SET NULL when the seller removes it later (the job row stays for the usage history).
    source_image_id BIGINT REFERENCES product_images (id) ON DELETE SET NULL,
    kind            TEXT        NOT NULL,
    status          TEXT        NOT NULL DEFAULT 'QUEUED',
    attempts        INT         NOT NULL DEFAULT 0,
    max_attempts    INT         NOT NULL,
    -- Stable machine-readable code of the last failure (e.g. ai.provider_error); never provider text.
    error_code      TEXT,
    idempotency_key UUID,
    created_by      BIGINT REFERENCES users (id) ON DELETE SET NULL,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT ai_jobs_kind CHECK (kind IN ('AI_PHOTOSHOOT', 'VIRTUAL_TRY_ON')),
    CONSTRAINT ai_jobs_status CHECK (status IN ('QUEUED', 'PROCESSING', 'REVIEW_REQUIRED', 'APPROVED', 'FAILED',
                                                'CANCELLED')),
    CONSTRAINT ai_jobs_attempts CHECK (attempts >= 0 AND max_attempts >= 1 AND attempts <= max_attempts),
    CONSTRAINT ai_jobs_idempotency_key UNIQUE (store_id, idempotency_key)
);

CREATE INDEX ai_jobs_product_idx ON ai_jobs (product_id, created_at DESC);
-- The worker takes the oldest queued job (FOR UPDATE SKIP LOCKED) and fails jobs stuck in PROCESSING.
CREATE INDEX ai_jobs_open_idx ON ai_jobs (status, updated_at) WHERE status IN ('QUEUED', 'PROCESSING');

CREATE TABLE ai_job_attempts
(
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    job_id      BIGINT        NOT NULL REFERENCES ai_jobs (id) ON DELETE CASCADE,
    number      INT           NOT NULL,
    provider    TEXT          NOT NULL,
    started_at  TIMESTAMPTZ   NOT NULL DEFAULT now(),
    finished_at TIMESTAMPTZ,
    outcome     TEXT,
    error_code  TEXT,
    -- Cost in the provider's currency: the estimate while running, the provider's figure when it reports one.
    cost        NUMERIC(12, 4) NOT NULL DEFAULT 0,
    currency    CHAR(3)       NOT NULL,
    CONSTRAINT ai_job_attempts_number UNIQUE (job_id, number),
    CONSTRAINT ai_job_attempts_outcome CHECK (outcome IS NULL OR outcome IN ('SUCCEEDED', 'FAILED')),
    CONSTRAINT ai_job_attempts_cost CHECK (cost >= 0)
);

CREATE TABLE ai_assets
(
    id               BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    job_id           BIGINT      NOT NULL REFERENCES ai_jobs (id) ON DELETE CASCADE,
    -- Private bucket key: ai/<store>/<product>/<uuid>.<ext>. NULL once the file is deleted (rejected job).
    storage_key      TEXT UNIQUE,
    content_type     TEXT        NOT NULL,
    width            INT         NOT NULL,
    height           INT         NOT NULL,
    size_bytes       BIGINT      NOT NULL,
    -- The product photo this asset became on approval.
    product_image_id BIGINT REFERENCES product_images (id) ON DELETE SET NULL,
    created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT ai_assets_type CHECK (content_type IN ('image/jpeg', 'image/png', 'image/webp')),
    CONSTRAINT ai_assets_size CHECK (width > 0 AND height > 0 AND size_bytes > 0)
);

CREATE INDEX ai_assets_job_idx ON ai_assets (job_id);

CREATE TABLE ai_approvals
(
    id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    job_id     BIGINT      NOT NULL REFERENCES ai_jobs (id) ON DELETE CASCADE,
    asset_id   BIGINT REFERENCES ai_assets (id) ON DELETE SET NULL,
    decision   TEXT        NOT NULL,
    decided_by BIGINT REFERENCES users (id) ON DELETE SET NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT ai_approvals_job UNIQUE (job_id),
    CONSTRAINT ai_approvals_decision CHECK (decision IN ('APPROVED', 'REJECTED')),
    CONSTRAINT ai_approvals_asset CHECK (decision <> 'APPROVED' OR asset_id IS NOT NULL)
);

CREATE TABLE ai_usage
(
    store_id   BIGINT         NOT NULL REFERENCES stores (id) ON DELETE CASCADE,
    -- Day in Asia/Baku.
    usage_date DATE           NOT NULL,
    -- Jobs and retries queued that day (the daily quota counts these).
    attempts   INT            NOT NULL DEFAULT 0,
    cost       NUMERIC(12, 4) NOT NULL DEFAULT 0,
    currency   CHAR(3)        NOT NULL,
    PRIMARY KEY (store_id, usage_date),
    CONSTRAINT ai_usage_values CHECK (attempts >= 0 AND cost >= 0)
);

-- The monthly hard cost limit sums all stores of a month.
CREATE INDEX ai_usage_date_idx ON ai_usage (usage_date);
